edits.before:
constructor(element?: string | Element | null, config?: Partial<DatepickerConfig> | null) {
  super(element, config)

  this._calendar = null
  this._isShown = false

  this._initCalendar()
}

  // Set initial value if input has a value
  if (this._isInput && this._element.value) {
    this._parseInputValue()
  }

  // Populate input/display with preselected dates
  this._updateDisplayWithSelectedDates()
}

edits.after:
  // Set initial value if input has a value
  if (this._isInput && this._element.value) {
    this._parseInputValue()
  }

  // Populate input/display with preselected dates
  this._updateDisplayWithSelectedDates()

  // Set up Tab key listener to hide the calendar when tabbing out
  if (this._isInput) {
    this._onTabKeyDown = (event: KeyboardEvent) => {
      if (event.key === 'Tab') {
        this.hide();
      }
    };
    EventHandler.on(this._element, 'keydown', this._onTabKeyDown);
  }
}

  if (this._calendar) {
    this._calendar.destroy()
  }

  // Clean up Tab key listener
  if (this._onTabKeyDown) {
    EventHandler.off(this._element, 'keydown', this._onTabKeyDown);
    this._onTabKeyDown = null;
  }

  this._calendar = null
  super.dispose()
}
